26	// disconnectedOnce ensures the disconnection warning runs at most once per process.
27	var disconnectedOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
28	
29	// IsMetadataDisconnected checks whether the local metadata branch
30	// and the provided fetched or remote-tracking ref exist but share no common
31	// ancestor.
32	func IsMetadataDisconnected(ctx context.Context, repo *git.Repository, remoteRefName plumbing.ReferenceName) (bool, error) {
33		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
34		localRef, err := repo.Reference(refName, true)
35		if errors.Is(err, plumbing.ErrReferenceNotFound) {
36			return false, nil
37		}
38		if err != nil {
39			return false, fmt.Errorf("failed to check local metadata branch: %w", err)
40		}
41	
42		remoteRef, err := repo.Reference(remoteRefName, true)
43		if errors.Is(err, plumbing.ErrReferenceNotFound) {
44			return false, nil
45		}
46		if err != nil {
47			return false, fmt.Errorf("failed to check remote metadata branch: %w", err)
48		}
49	
50		if localRef.Hash() == remoteRef.Hash() {
51			return false, nil
52		}
53	
54		repoPath, err := getRepoPath(repo)
55		if err != nil {
56			return false, err
57		}
58	
59		return isDisconnected(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
60	}
