92	// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
93	// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
94	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
95	// and handled by the push path's tree merge.
96	//
97	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
98	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
99	// apply cleanly.
100	//
101	// Progress messages are written to w (typically os.Stderr for hooks or
102	// cmd.ErrOrStderr() for commands).
103	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
104	func ReconcileDisconnectedMetadataBranch(
105		ctx context.Context,
106		repo *git.Repository,
107		remoteRefName plumbing.ReferenceName,
108		w io.Writer,
109	) error {
110		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
111	
112		// Check local branch
113		localRef, err := repo.Reference(refName, true)
114		if errors.Is(err, plumbing.ErrReferenceNotFound) {
115			return nil // No local branch — nothing to reconcile
116		}
117		if err != nil {
118			return fmt.Errorf("failed to check local metadata branch: %w", err)
119		}
120	
121		// Check remote-tracking branch
122		remoteRef, err := repo.Reference(remoteRefName, true)
123		if errors.Is(err, plumbing.ErrReferenceNotFound) {
124			return nil // No remote branch — nothing to reconcile
125		}
126		if err != nil {
127			return fmt.Errorf("failed to check remote metadata branch: %w", err)
128		}
129	
130		localHash := localRef.Hash()
131		remoteHash := remoteRef.Hash()
132	
133		// Same hash — nothing to do
134		if localHash == remoteHash {
135			return nil
136		}
137	
138		// Check if disconnected using git merge-base
139		repoPath, err := getRepoPath(repo)
140		if err != nil {
141			return err
142		}
143	
144		disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
145		if err != nil {
146			return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
147		}
148		if !disconnected {
149			// Shared ancestry (diverged or ancestor) — not our problem
150			return nil
151		}
152	
153		// Disconnected — cherry-pick local commits onto remote tip
154		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
155	
156		// Collect local commits oldest-first
157		localCommits, err := collectCommitChain(repo, localHash)
158		if err != nil {
159			return fmt.Errorf("failed to collect local commits: %w", err)
160		}
161	
162		// Filter out empty-tree commits (the orphan bug commit)
163		var dataCommits []*object.Commit
164		for _, c := range localCommits {
165			tree, treeErr := c.Tree()
166			if treeErr != nil {
167				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
168			}
169			if len(tree.Entries) > 0 {
170				dataCommits = append(dataCommits, c)
171			}
172		}
173	
174		if len(dataCommits) == 0 {
175			// Local only had empty orphan — just point to remote
176			ref := plumbing.NewHashReference(refName, remoteHash)
177			if err := repo.Storer.SetReference(ref); err != nil {
178				return fmt.Errorf("failed to reset metadata branch to remote: %w", err)
179			}
180			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
181			return nil
182		}
183	
184		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
185	
186		newTip, err := cherryPickOnto(ctx, repo, remoteHash, dataCommits)
187		if err != nil {
188			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
189		}
190	
191		// Update local branch ref
192		ref := plumbing.NewHashReference(refName, newTip)
193		if err := repo.Storer.SetReference(ref); err != nil {
194			return fmt.Errorf("failed to update metadata branch: %w", err)
195		}
196	
197		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
198		return nil
199	}
