201	// v2DoctorTmpRef is the temporary ref used by doctor to fetch and compare the remote v2 /main.
202	// Uses the refs/entire-fetch-tmp/ namespace consistent with checkpoint_remote.go.
203	const v2DoctorTmpRef = "refs/entire-fetch-tmp/doctor-v2-main"
204	
205	// IsV2MainDisconnected checks whether the local v2 /main ref and the remote
206	// v2 /main ref exist but share no common ancestor. Uses git ls-remote to
207	// discover the remote ref (custom refs don't have remote-tracking refs).
208	//
209	// remote is the git remote name, URL, or local path to check against.
210	// Returns (false, nil) if either ref doesn't exist or they share ancestry.
211	func IsV2MainDisconnected(ctx context.Context, repo *git.Repository, remote string) (bool, error) {
212		refName := plumbing.ReferenceName(paths.V2MainRefName)
213	
214		localRef, err := repo.Reference(refName, true)
215		if errors.Is(err, plumbing.ErrReferenceNotFound) {
216			return false, nil
217		}
218		if err != nil {
219			return false, fmt.Errorf("failed to check local v2 /main ref: %w", err)
220		}
221	
222		repoPath, err := getRepoPath(repo)
223		if err != nil {
224			return false, err
225		}
226	
227		remoteHash, err := lsRemoteRef(ctx, repoPath, remote, paths.V2MainRefName)
228		if err != nil {
229			return false, fmt.Errorf("failed to ls-remote v2 /main: %w", err)
230		}
231		if remoteHash == plumbing.ZeroHash {
232			return false, nil // Remote doesn't have the ref
233		}
234	
235		if localRef.Hash() == remoteHash {
236			return false, nil
237		}
238	
239		// Fetch remote ref to temporary local ref for merge-base check.
240		// Use the fetched hash (not ls-remote hash) since the remote may have advanced.
241		if fetchErr := fetchRefToTemp(ctx, repoPath, remote, paths.V2MainRefName, v2DoctorTmpRef); fetchErr != nil {
242			return false, fmt.Errorf("failed to fetch remote v2 /main: %w", fetchErr)
243		}
244		defer cleanupTmpRef(repo)
245	
246		fetchedHash, err := resolveRefHash(repo, v2DoctorTmpRef)
247		if err != nil {
248			return false, fmt.Errorf("failed to read fetched v2 /main ref: %w", err)
249		}
250	
251		if localRef.Hash() == fetchedHash {
252			return false, nil
253		}
254	
255		return isDisconnected(ctx, repoPath, localRef.Hash().String(), fetchedHash.String())
256	}
