286			return fmt.Errorf("failed to ls-remote v2 /main: %w", err)
287		}
288		if remoteHash == plumbing.ZeroHash {
289			return nil
290		}
291	
292		if localRef.Hash() == remoteHash {
293			return nil
294		}
295	
296		if fetchErr := fetchRefToTemp(ctx, repoPath, remote, paths.V2MainRefName, v2DoctorTmpRef); fetchErr != nil {
297			return fmt.Errorf("failed to fetch remote v2 /main: %w", fetchErr)
298		}
