317		}
318	
319		fmt.Fprintln(w, "[entire] Detected disconnected v2 /main refs (local and remote share no common ancestor)")
320	
321		localCommits, err := collectCommitChain(repo, localRef.Hash())
322		if err != nil {
323			return fmt.Errorf("failed to collect local commits: %w", err)
324		}
325	
326		var dataCommits []*object.Commit
327		for _, c := range localCommits {
328			tree, treeErr := c.Tree()
