362	// lsRemoteRef runs git ls-remote and returns the hash for a specific ref.
363	// Returns plumbing.ZeroHash if the ref doesn't exist on the remote.
364	func lsRemoteRef(ctx context.Context, repoPath, remoteName, refName string) (plumbing.Hash, error) {
365		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
366		defer cancel()
367	
368		fetchTarget, err := remote.ResolveFetchTarget(ctx, remoteName)
369		if err != nil {
370			return plumbing.ZeroHash, fmt.Errorf("resolve fetch target for ls-remote: %w", err)
371		}
372	
373		output, err := remote.LsRemoteInDir(ctx, repoPath, fetchTarget, refName)
374		if err != nil {
375			return plumbing.ZeroHash, fmt.Errorf("git ls-remote %s failed: %w", remote.RedactURL(fetchTarget), err)
376		}
377	
378		line := strings.TrimSpace(string(output))
379		if line == "" {
380			return plumbing.ZeroHash, nil
381		}
382	
383		parts := strings.Fields(line)
384		if len(parts) < 2 {
385			return plumbing.ZeroHash, nil
386		}
387	
388		return plumbing.NewHash(parts[0]), nil
389	}
