391	// fetchRefToTemp fetches a remote ref to a temporary local ref for comparison.
392	func fetchRefToTemp(ctx context.Context, repoPath, remoteName, srcRef, dstRef string) error {
393		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
394		defer cancel()
395	
396		fetchTarget, err := remote.ResolveFetchTarget(ctx, remoteName)
397		if err != nil {
398			return fmt.Errorf("resolve fetch target for doctor v2 fetch: %w", err)
399		}
400	
401		refspec := fmt.Sprintf("+%s:%s", srcRef, dstRef)
402		output, err := remote.Fetch(ctx, remote.FetchOptions{
403			Remote:   fetchTarget,
404			RefSpecs: []string{refspec},
405			NoTags:   true,
406			Dir:      repoPath,
407		})
408		if err != nil {
409			redactedURL := remote.RedactURL(fetchTarget)
410			msg := strings.TrimSpace(strings.ReplaceAll(string(output), fetchTarget, redactedURL))
411			if msg != "" {
412				return fmt.Errorf("git fetch %s failed: %s: %w", redactedURL, msg, err)
413			}
414			return fmt.Errorf("git fetch %s failed: %w", redactedURL, err)
415		}
416		return nil
417	}
