419	// resolveRefHash reads the commit hash that a ref points to.
420	func resolveRefHash(repo *git.Repository, refName string) (plumbing.Hash, error) {
421		ref, err := repo.Reference(plumbing.ReferenceName(refName), true)
422		if err != nil {
423			return plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
424		}
425		return ref.Hash(), nil
426	}
