428	// cleanupTmpRef deletes the temporary ref used by doctor checks.
429	func cleanupTmpRef(repo *git.Repository) {
430		_ = repo.Storer.RemoveReference(plumbing.ReferenceName(v2DoctorTmpRef)) //nolint:errcheck // best-effort cleanup
431	}
