433	// isDisconnected checks if two commits have no common ancestor using git merge-base.
434	// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
435	// or (false, error) if git merge-base failed for another reason.
436	//
437	// git merge-base exit codes:
438	//   - 0: common ancestor found (shared ancestry)
439	//   - 1: no common ancestor (disconnected)
440	//   - 128+: error (corrupt repo, invalid hash, etc.)
441	func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
442		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
443		defer cancel()
444		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
445		cmd.Dir = repoPath
446		if err := cmd.Run(); err != nil {
447			var exitErr *exec.ExitError
448			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
449				return true, nil // No common ancestor — disconnected
450			}
451			return false, fmt.Errorf("git merge-base failed: %w", err)
452		}
453		return false, nil // Shared ancestry
454	}
