456	// collectCommitChain walks from tip to root following first parent, returns oldest-first.
457	func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
458		var chain []*object.Commit
459		current := tip
460	
461		reachedRoot := false
462		for range MaxCommitTraversalDepth {
463			commit, err := repo.CommitObject(current)
464			if err != nil {
465				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
466			}
467			chain = append(chain, commit)
468	
469			if len(commit.ParentHashes) == 0 {
470				reachedRoot = true
471				break
472			}
473			current = commit.ParentHashes[0]
474		}
475	
476		if !reachedRoot {
477			return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
478		}
479	
480		// Reverse to oldest-first
481		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
482			chain[i], chain[j] = chain[j], chain[i]
483		}
484	
485		return chain, nil
486	}
