488	// cherryPickOnto applies each commit's delta onto base, building a linear chain.
489	// For each commit, it computes the full diff from its parent (additions, modifications,
490	// and deletions), then applies that delta onto the current tip's tree.
491	func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit) (plumbing.Hash, error) {
492		currentTip := base
493	
494		for _, commit := range commits {
495			changes, err := treeChangesForCherryPick(ctx, repo, commit)
496			if err != nil {
497				return plumbing.ZeroHash, err
498			}
499			if len(changes) == 0 {
500				continue // Skip no-op commits
501			}
502	
503			tipCommit, err := repo.CommitObject(currentTip)
504			if err != nil {
505				return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
506			}
507	
508			mergedTreeHash, err := checkpoint.ApplyTreeChanges(ctx, repo, tipCommit.TreeHash, changes)
509			if err != nil {
510				return plumbing.ZeroHash, fmt.Errorf("failed to apply cherry-pick changes: %w", err)
511			}
512	
513			// Create new commit on top of current tip, preserving original message/author
514			newHash, err := createCherryPickCommit(ctx, repo, mergedTreeHash, currentTip, commit)
515			if err != nil {
516				return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
517			}
518	
519			currentTip = newHash
520		}
521	
522		return currentTip, nil
523	}
