525	func treeChangesForCherryPick(ctx context.Context, repo *git.Repository, commit *object.Commit) ([]checkpoint.TreeChange, error) {
526		commitTree, err := commit.Tree()
527		if err != nil {
528			return nil, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
529		}
530	
531		var parentTree *object.Tree
532		if len(commit.ParentHashes) > 0 {
533			parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
534			if pErr != nil {
535				return nil, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
536			}
537			parentTree, err = parentCommit.Tree()
538			if err != nil {
539				return nil, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], err)
540			}
541		}
542	
543		changes, err := object.DiffTreeContext(ctx, parentTree, commitTree)
544		if err != nil {
545			return nil, fmt.Errorf("failed to diff commit %s against parent: %w", commit.Hash, err)
546		}
547	
548		treeChanges := make([]checkpoint.TreeChange, 0, len(changes))
549		for _, change := range changes {
550			treeChange, changeErr := changeToTreeChange(change)
551			if changeErr != nil {
552				return nil, fmt.Errorf("failed to convert change in commit %s: %w", commit.Hash, changeErr)
553			}
554			treeChanges = append(treeChanges, treeChange)
555		}
556		return treeChanges, nil
557	}
558	
559	func changeToTreeChange(change *object.Change) (checkpoint.TreeChange, error) {
560		action, err := change.Action()
561		if err != nil {
562			return checkpoint.TreeChange{}, fmt.Errorf("change action: %w", err)
563		}
564	
565		switch action {
566		case merkletrie.Insert, merkletrie.Modify:
567			entry := change.To.TreeEntry
568			return checkpoint.TreeChange{
569				Path: change.To.Name,
570				Entry: &object.TreeEntry{
571					Name: entry.Name,
572					Mode: entry.Mode,
573					Hash: entry.Hash,
574				},
575			}, nil
576		case merkletrie.Delete:
577			return checkpoint.TreeChange{Path: change.From.Name}, nil
578		default:
579			return checkpoint.TreeChange{}, fmt.Errorf("unsupported action %s", action)
580		}
581	}
