583	// createCherryPickCommit creates a new commit on top of parent, preserving the
584	// original commit's message and author.
585	func createCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
586		committerName, committerEmail := GetGitAuthorFromRepo(repo)
587		now := time.Now()
588	
589		commit := &object.Commit{
590			TreeHash:     treeHash,
591			ParentHashes: []plumbing.Hash{parent},
592			Author:       original.Author,
593			Committer: object.Signature{
594				Name:  committerName,
595				Email: committerEmail,
596				When:  now,
597			},
598			Message: original.Message,
599		}
600	
601		checkpoint.SignCommitBestEffort(ctx, commit)
602	
603		obj := repo.Storer.NewEncodedObject()
604		if err := commit.Encode(obj); err != nil {
605			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
606		}
607	
608		hash, err := repo.Storer.SetEncodedObject(obj)
609		if err != nil {
610			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
611		}
612	
613		return hash, nil
614	}
