616	// getRepoPath returns the filesystem path for the repository's worktree.
617	func getRepoPath(repo *git.Repository) (string, error) {
618		wt, err := repo.Worktree()
619		if err != nil {
620			return "", fmt.Errorf("failed to get worktree: %w", err)
621		}
622		return wt.Filesystem().Root(), nil
623	}
