139	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
140	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
141	// entire.io discovers the external checkpoint repo by reading the committed project
142	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
143	// (not just in settings.local.json or uncommitted local changes).
144	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
145	// single pre-push invocation.
146	func printSettingsCommitHint(ctx context.Context, target string) {
147		if !remote.IsURL(target) {
148			return
149		}
150		settingsHintOnce.Do(func() {
151			if isCheckpointRemoteCommitted(ctx) {
152				return
153			}
154			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
155		})
156	}
