158	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
159	// at HEAD contains a valid checkpoint_remote configuration. This is the true
160	// discoverability check: entire.io reads from committed project settings, not from
161	// local overrides or uncommitted changes.
162	func isCheckpointRemoteCommitted(ctx context.Context) bool {
163		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
164		output, err := cmd.Output()
165		if err != nil {
166			return false // file doesn't exist at HEAD
167		}
168		// Parse the committed content and check for checkpoint_remote
169		committed, err := settings.LoadFromBytes(output)
170		if err != nil {
171			return false
172		}
173		return committed.GetCheckpointRemote() != nil
174	}
