182	// parsePushResult checks git push --porcelain output for ref status flags.
183	// In porcelain mode, each ref gets a tab-delimited status line:
184	//
185	//	<flag>\t<from>:<to>\t<summary>
186	//
187	// where flag '=' means the ref was already up-to-date. This is locale-independent,
188	// unlike the human-readable "Everything up-to-date" message.
189	func parsePushResult(output string) pushResult {
190		for _, line := range strings.Split(output, "\n") {
191			if strings.HasPrefix(line, "=\t") {
192				return pushResult{upToDate: true}
193			}
194		}
195		return pushResult{upToDate: false}
196	}
