198	// finishPush stops the progress dots and prints "already up-to-date" or "done"
199	// depending on the push result. Only prints the settings commit hint when new
200	// content was actually pushed.
201	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
202		if result.upToDate {
203			stop(" already up-to-date")
204		} else {
205			stop(" done")
206			printSettingsCommitHint(ctx, target)
207		}
208	}
