210	// tryPushSessionsCommon attempts to push the sessions branch.
211	func tryPushSessionsCommon(ctx context.Context, remoteName, branchName string) (pushResult, error) {
212		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
213		defer cancel()
214	
215		result, err := remote.Push(ctx, remoteName, branchName)
216		outputStr := result.Output
