233	// isProtectedRefRejection detects GitHub ruleset and branch-protection failures.
234	func isProtectedRefRejection(output string) bool {
235		return strings.Contains(output, "GH013") ||
236			strings.Contains(output, "Cannot update this protected ref") ||
237			strings.Contains(output, "protected branch hook declined")
238	}
239	
240	var errNonFastForward = errors.New("non-fast-forward")
241	
242	func isNonFastForwardRejection(output string) bool {
243		if strings.Contains(output, "non-fast-forward") {
244			return true
245		}
246		for _, line := range strings.Split(output, "\n") {
247			if strings.Contains(line, "[rejected]") && strings.Contains(line, "(fetch first)") {
248				return true
249			}
250		}
251		return strings.Contains(output, "Updates were rejected because the tip of your current branch is behind") ||
252			strings.Contains(output, "Updates were rejected because the remote contains work that you do not have locally")
253	}
254	
255	// classifyPushOutput maps failing push stderr to a typed error.
256	func classifyPushOutput(output string) error {
257		if isProtectedRefRejection(output) {
258			return &protectedRefError{output: output}
259		}
260		if isNonFastForwardRejection(output) {
261			return errNonFastForward
262		}
263		if strings.TrimSpace(output) == "" {
264			return errors.New("push failed")
265		}
266		return fmt.Errorf("push failed: %s", output)
267	}
268	
269	func classifyPushFailure(ctx context.Context, output string, pushErr error) error {
270		if strings.TrimSpace(output) != "" {
271			if pushErr != nil {
272				logging.Debug(ctx, "git push failed",
273					slog.String("error", pushErr.Error()),
274					slog.String("output", output),
275				)
276			}
277			return classifyPushOutput(output)
278		}
279		if pushErr != nil {
280			logging.Debug(ctx, "git push failed without output",
281				slog.String("error", pushErr.Error()),
282			)
283			return fmt.Errorf("push failed: %w", pushErr)
284		}
285		return errors.New("push failed")
286	}
