288	// printProtectedRefBlock explains that checkpoint syncing was blocked remotely.
289	func printProtectedRefBlock(w io.Writer, ref, target string) {
290		const banner = "[entire] ============================================================"
291		displayTarget := displayPushTarget(target)
292		fmt.Fprintln(w, banner)
293		fmt.Fprintf(w, "[entire] BLOCKED: remote rejected push to %s\n", ref)
294		fmt.Fprintln(w, "[entire] Reason:  GitHub branch protection or repository ruleset (e.g. GH013)")
295		fmt.Fprintf(w, "[entire] Target:  %s\n", displayTarget)
296		fmt.Fprintln(w, "[entire] Impact:  checkpoints are saved locally but NOT synced to this remote.")
297		fmt.Fprintln(w, "[entire] Action:  allow pushes to `entire/*` in your ruleset, or set")
