302	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
303	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
304	// always apply cleanly.
305	// The target can be a remote name or a URL.
306	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
307		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
308		defer cancel()
309	
310		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
311		if err != nil {
312			return fmt.Errorf("resolve fetch target: %w", err)
313		}
314	
315		// Determine fetch refspec. When the resolved fetch target is a URL, use a
316		// temp ref; when it's still a remote name, use the standard remote-tracking
317		// ref.
318		var fetchedRefName plumbing.ReferenceName
319		var refSpec string
320		usedTempRef := remote.IsURL(fetchTarget)
321		if usedTempRef {
322			tmpRef := "refs/entire-fetch-tmp/" + branchName
323			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
324			fetchedRefName = plumbing.ReferenceName(tmpRef)
325		} else {
326			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
327			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
328		}
329	
330		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
331		// Use --filter=blob:none for a partial fetch that downloads only commits
332		// and trees, skipping blobs. The merge only needs the tree structure to
333		// combine entries; blobs are already local or fetched on demand.
334		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
335			Remote:   fetchTarget,
336			RefSpecs: []string{refSpec},
337			NoTags:   true,
338		}); fetchErr != nil {
339			return fmt.Errorf("fetch failed: %s", output)
340		}
341	
342		repo, err := OpenRepository(ctx)
343		if err != nil {
344			return fmt.Errorf("failed to open git repository: %w", err)
345		}
346	
347		// Reconcile disconnected metadata branches before rebasing.
348		// The fetch above updated the remote-tracking ref, so reconciliation
349		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
350		// this cherry-picks local commits onto remote tip, updating the local ref.
351		// If reconciliation fails, abort — proceeding to rebase on disconnected
352		// branches would silently combine unrelated histories.
353		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
354			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
355		}
356	
357		// Get local branch (re-read after potential reconciliation update)
358		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
359		if err != nil {
360			return fmt.Errorf("failed to get local ref: %w", err)
361		}
362	
363		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
364		remoteRef, err := repo.Reference(fetchedRefName, true)
365		if err != nil {
366			return fmt.Errorf("failed to get remote ref: %w", err)
367		}
368	
369		// If local is already at or behind remote, fast-forward
370		if localRef.Hash() == remoteRef.Hash() {
371			return nil
372		}
373	
374		// Find merge base
375		repoPath, err := getRepoPath(repo)
376		if err != nil {
377			return fmt.Errorf("failed to get repo path: %w", err)
378		}
379		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
380		if err != nil {
381			return fmt.Errorf("failed to find merge base: %w", err)
382		}
383	
384		// If local is ancestor of remote (merge base == local), fast-forward to remote
385		if mergeBase == localRef.Hash() {
386			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
387			if err := repo.Storer.SetReference(ref); err != nil {
388				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
389			}
390			if usedTempRef {
391				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
392			}
393			return nil
394		}
395	
396		// Collect commits reachable from local but not from remote and cherry-pick
397		// them onto the remote tip. This preserves local-only commits even when the
398		// local metadata branch already contains old merge commits, while avoiding
399		// replaying shared ancestors older than the true merge-base.
400		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
401		if err != nil {
402			return fmt.Errorf("failed to collect local commits: %w", err)
403		}
404	
405		if len(localCommits) == 0 {
406			// No local-only commits — just point to remote
407			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
408			if err := repo.Storer.SetReference(ref); err != nil {
409				return fmt.Errorf("failed to update branch ref: %w", err)
410			}
411			if usedTempRef {
412				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
413			}
414			return nil
415		}
416	
417		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
418		if err != nil {
419			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
420		}
421	
422		// Update branch ref
423		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
424		if err := repo.Storer.SetReference(newRef); err != nil {
425			return fmt.Errorf("failed to update branch ref: %w", err)
426		}
427	
428		// Clean up temp ref if we used one (best-effort, not critical if it fails)
429		if usedTempRef {
430			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
431		}
432	
433		return nil
434	}
