436	// getMergeBase returns the merge base hash of two commits, or an error if they
437	// have no common ancestor.
438	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
439		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
440		defer cancel()
441	
442		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
443		cmd.Dir = repoPath
444		output, err := cmd.Output()
445		if err != nil {
446			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
447		}
448	
449		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
450	}
