452	// collectCommitsSince returns non-merge commits reachable from tip but not from
453	// exclude, ordered oldest-first in topological order.
454	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
455		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
456		defer cancel()
457	
458		// cherryPickOnto computes each commit's delta against its first parent, so
459		// replaying merge commits would incorrectly re-apply changes that arrived via
460		// non-first-parent history. Limit the replay set to non-merge commits.
461		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
462		cmd.Dir = repoPath
463		output, err := cmd.Output()
464		if err != nil {
465			return nil, fmt.Errorf("git rev-list failed: %w", err)
466		}
467	
468		lines := strings.Fields(string(output))
469		if len(lines) > MaxCommitTraversalDepth {
470			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
471		}
472	
473		commits := make([]*object.Commit, 0, len(lines))
474		for _, line := range lines {
475			hash := plumbing.NewHash(line)
476			commit, commitErr := repo.CommitObject(hash)
477			if commitErr != nil {
478				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
479			}
480			if len(commit.ParentHashes) > 1 {
481				continue
482			}
483			commits = append(commits, commit)
484		}
485	
486		return commits, nil
487	}
