489	// startProgressDots prints dots to w every second until the returned stop function
490	// is called. The stop function prints the given suffix and a newline.
491	func startProgressDots(w io.Writer) func(suffix string) {
492		done := make(chan struct{})
493		stopped := make(chan struct{})
494		go func() {
495			defer close(stopped)
496			ticker := time.NewTicker(time.Second)
497			defer ticker.Stop()
498			for {
499				select {
500				case <-done:
501					return
502				case <-ticker.C:
503					fmt.Fprint(w, ".")
504				}
505			}
506		}()
507		return func(suffix string) {
508			close(done)
509			<-stopped // Wait for goroutine to finish before writing suffix
510			fmt.Fprintln(w, suffix)
511		}
512	}
